export interface SiteCapacity { used: number; limit: number }

export abstract class CapacityLedger {
  protected readonly stored: Array<SiteCapacity | undefined> = [];
  private totalUsed = 0;
  private totalLimit = 0;

  get used(): number {
    return this.totalUsed;
  }

  get limit(): number {
    return this.totalLimit;
  }

  protected setTotals(used: number, limit: number): void {
    this.totalUsed = used;
    this.totalLimit = limit;
  }

  get sites(): readonly (Readonly<SiteCapacity> | undefined)[] {
    const snapshot = Array.from(
      { length: this.stored.length },
      (_, index) => {
        const site = this.stored[index];
        return site === undefined
          ? undefined
          : Object.freeze({ used: site.used, limit: site.limit });
      },
    );
    return Object.freeze(snapshot);
  }

  setSite(site: SiteCapacity, index: number): void {
    if (!Number.isInteger(index) || index < 0) {
      throw new RangeError("invalid index");
    }

    if (
      site === null ||
      typeof site !== "object" ||
      !Number.isFinite(site.used) ||
      !Number.isFinite(site.limit) ||
      site.limit <= 0 ||
      site.used < 0 ||
      site.used > site.limit
    ) {
      throw new RangeError("invalid site capacity");
    }

    const copy: SiteCapacity = { used: site.used, limit: site.limit };
    this.stored[index] = copy;
    this.recalculate();
  }

  protected abstract recalculate(): void;
}

export class RegionalCapacityLedger extends CapacityLedger {
  private averageUtilization = 0;

  get meanUtilization(): number {
    return this.averageUtilization;
  }

  protected recalculate(): void {
    let used = 0;
    let limit = 0;

    for (const site of this.stored) {
      if (site !== undefined) {
        used += site.used;
        limit += site.limit;
      }
    }

    this.setTotals(used, limit);
    this.averageUtilization = limit === 0 ? 0 : used / limit;
  }
}

