import { RegionalCapacityLedger } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function approx(actual: number, expected: number, message: string): void {
  if (Math.abs(actual - expected) > 1e-12) throw new Error(`${message}: expected ${expected}, got ${actual}`);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const ledger = new RegionalCapacityLedger();
approx(ledger.used, 0, 'empty used');
approx(ledger.limit, 0, 'empty limit');
approx(ledger.meanUtilization, 0, 'empty mean');
const emptySites = ledger.sites;
assert(Object.isFrozen(emptySites), 'empty sites snapshot frozen');
assert(emptySites.length === 0, 'empty sites snapshot');

const first = { used: 2, limit: 4 };
ledger.setSite(first, 0);
first.used = 4;
approx(ledger.used, 2, 'input copied');
approx(ledger.limit, 4, 'first limit');
approx(ledger.meanUtilization, 0.5, 'first mean');

ledger.setSite({ used: 9, limit: 10 }, 2);
approx(ledger.used, 11, 'sparse total used');
approx(ledger.limit, 14, 'sparse total limit');
approx(ledger.meanUtilization, 0.7, 'mean uses individual ratios');
const snapshot = ledger.sites;
assert(snapshot.length === 3, 'sparse snapshot length');
assert(0 in snapshot && 1 in snapshot && 2 in snapshot, 'holes represented as explicit values');
assert(snapshot[1] === undefined, 'sparse slot is undefined');
assert(Object.isFrozen(snapshot), 'sites array frozen');
assert(Object.isFrozen(snapshot[0]!), 'defined site frozen');
assert(Object.isFrozen(snapshot[2]!), 'second defined site frozen');
const anotherSnapshot = ledger.sites;
assert(anotherSnapshot !== snapshot, 'getter returns new array');
assert(anotherSnapshot[0] !== snapshot[0], 'getter returns new site copies');

ledger.setSite({ used: 1, limit: 2 }, 0);
approx(ledger.used, 10, 'replacement used');
approx(ledger.limit, 12, 'replacement limit');
approx(ledger.meanUtilization, 0.7, 'replacement mean');
approx(snapshot[0]!.used, 2, 'older snapshot remains stable');

const before = ledger.sites;
const beforeUsed = ledger.used;
for (const site of [
  { used: -1, limit: 1 }, { used: 2, limit: 1 }, { used: 0, limit: 0 },
  { used: NaN, limit: 1 }, { used: 0, limit: Infinity },
]) {
  throwsRange(() => ledger.setSite(site, 1), 'invalid site');
  approx(ledger.used, beforeUsed, 'invalid site leaves totals unchanged');
}
for (const index of [-1, 0.5, Infinity, NaN]) {
  throwsRange(() => ledger.setSite({ used: 0, limit: 1 }, index), 'invalid index');
}
const after = ledger.sites;
approx(after[0]!.used, before[0]!.used, 'failed operations leave sites unchanged');
assert(after[1] === undefined, 'failed operations do not fill sparse slot');

